class Solution {private int lower;private int upper;private long[] prefixSums;private int count = 0;public int countRangeSum(int[] nums, int lower, int upper) {this.lower = lower;this.upper = upper;int n = nums.length;prefixSums = new long[n + 1];prefixSums[0] = 0;for (int i = 0; i < n; i++) {prefixSums[i + 1] = prefixSums[i] + nums[i];}mergeSortAndCount(0, n + 1);return count;}private void mergeSortAndCount(int start, int end) {if (end - start <= 1) {return;}int mid = start + (end - start) / 2;mergeSortAndCount(start, mid);mergeSortAndCount(mid, end);int j = start;int l = start;for (int k = mid; k < end; k++) {while (j < mid && prefixSums[j] < prefixSums[k] - upper) {j++;}while (l < mid && prefixSums[l] <= prefixSums[k] - lower) {l++;}count += (l - j);}long[] temp = new long[end - start];int p1 = start, p2 = mid, current = 0;while (p1 < mid && p2 < end) {if (prefixSums[p1] < prefixSums[p2]) {temp[current++] = prefixSums[p1++];} else {temp[current++] = prefixSums[p2++];}}while (p1 < mid) {temp[current++] = prefixSums[p1++];}while (p2 < end) {temp[current++] = prefixSums[p2++];}System.arraycopy(temp, 0, prefixSums, start, end - start);}}